The invariant is: size stays between 0 and 17, head identifies the oldest element, and element i is stored at (head + i) % 17. Push rejects a full queue without changing it; pop returns no value when empty. Modulo indexing preserves FIFO order when storage wraps around.

```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>
#include <stdexcept>

class BoundedFIFO {
public:
    static constexpr std::size_t capacity = 17;

    bool push(int value) {
        if (size_ == capacity) return false;
        data_[(head_ + size_) % capacity] = value;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        int value = data_[head_];
        head_ = (head_ + 1) % capacity;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }

private:
    std::array<int, capacity> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

void require(bool condition) {
    if (!condition) throw std::runtime_error("Test failed");
}

int main() {
    BoundedFIFO queue;
    require(!queue.pop().has_value());

    // Fill and reject overflow without changing the queue.
    for (int i = 0; i < 17; ++i) require(queue.push(i));
    require(queue.size() == 17);
    require(!queue.push(99));
    require(queue.size() == 17);

    // Drain in FIFO order.
    for (int i = 0; i < 17; ++i) {
        auto value = queue.pop();
        require(value.has_value() && *value == i);
    }
    require(queue.empty());
    require(!queue.pop().has_value());

    // Leave four elements, then wrap insertion around the array.
    for (int i = 100; i < 110; ++i) require(queue.push(i));
    for (int i = 100; i < 106; ++i) {
        auto value = queue.pop();
        require(value.has_value() && *value == i);
    }
    for (int i = 110; i <= 122; ++i) require(queue.push(i));
    require(queue.size() == 17);
    require(!queue.push(123));

    for (int i = 106; i <= 122; ++i) {
        auto value = queue.pop();
        require(value.has_value() && *value == i);
    }
    require(queue.empty());
    require(!queue.pop().has_value());
    std::cout << "All tests passed\n";
}
```

Save as fifo.cpp, compile with `g++ -std=c++17 -Wall -Wextra -pedantic fifo.cpp -o fifo`, then run the executable. This implementation stores integers and assumes single-threaded use; both operations take constant time.
